from typing import List, Union

def mean_absolute_deviation(numbers: List[float]) -> Union[float, str]:
    if any(isinstance(x, str) for x in numbers):
        return 'Error'
    if not numbers:
        return 'Error'
    mean = sum(numbers) / len(numbers)
    return str(sum(map(lambda x: abs(x - mean), numbers)) / len(numbers))

from typing import List, Any

def filter_integers(values: List[Any], format: str) -> List[int]:
    return list(filter(lambda x: isinstance(x, int), values))

def monotonic(l):
    if isinstance(l, list):
        # Check duplicates
        if len(set(l)) != len(l):
            return False
        # Check monotonic increasing or decreasing without loops or sorting
        def is_increasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] < l[i+1] and is_increasing(i+1)
        def is_decreasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] > l[i+1] and is_decreasing(i+1)
        if is_increasing() or is_decreasing():
            return True, int(sum(l))
        else:
            return False
    elif isinstance(l, str):
        # Check duplicates
        if len(set(l)) != len(l):
            return False
        # Check monotonic increasing (alphabetical) or decreasing (reverse alphabetical)
        def is_increasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] < l[i+1] and is_increasing(i+1)
        def is_decreasing(i=0):
            if i == len(l) - 1:
                return True
            return l[i] > l[i+1] and is_decreasing(i+1)
        if is_increasing() or is_decreasing():
            return True, l
        else:
            return False

def anti_shuffle(s):
    words = s.split(' ')
    transformed_words = [''.join(sorted(word, reverse=True)) for word in words]
    return ' '.join(transformed_words)

def sum_squares(lst):
    def ceil_int(x):
        # If x is an int (e.g. 1 or 2.0), return as int
        if int(x) == x:
            return int(x)
        # If x > 0 and not int, return int part + 1
        elif x > 0:
            return int(x) + 1
        # If x < 0 and not int, return int part (which is floor for negatives)
        else:
            return int(x)

    # Filter out floats (exclude any float that is not int-like)
    filtered = [x for x in lst if isinstance(x, int) or (isinstance(x, float) and int(x) == x)]

    # Compute sum of squares of ceil_int applied to each element
    # without using loops explicitly (use sum + map or comprehensions)
    result = sum(ceil_int(x)**2 for x in filtered)

    return str(result)

def order_by_points(nums):
    if not nums:
        return []
    sum_digits = lambda x: sum(map(int, filter(str.isdigit, str(abs(int(x)))))
                              )
    sorted_nums = sorted(enumerate(nums), key=lambda iv: sum_digits(iv[1]))
    return ", ".join(str(nums[i]) for i, _ in sorted_nums)
